/* Goals and badges per ski area (28 Nov 2026; pure: no THREE, no DOM; the Node checks use the same code).
 * Every area has the same generic goals, derived from its data (modes/goals-data.js, generated by scripts/ski/goals_data.mjs):
 *   lifts    ride every lift                      (bits of modes/lift-index.js, saved as progress.lifts[rid])
 *   black / red / blue / green / pistes   finish every counted piste of that colour (>= 400 m) once: star 1 of the star index
 *   stars    collect a share of the stars         (20 % of the possible stars of the counted pistes)
 *   disc     discover most of the area            (cells within 150 m of a piste or lift: modes/discovery.js)
 *   top      reach the highest lift top
 *   park     finish a run in the snow park / park points
 * What is saved: only what cannot be derived. Stars, discovery, park points and the lift bits are the progress; a REACHED goal is a bit in
 * progress.goals[rid] (monotone: a badge is never lost, even when the cloud record had to drop the fog or the lifts). */
import { PISTE_INDEX } from './piste-index.js';
import { LIFT_INDEX } from './lift-index.js';
import { GOALS_DATA } from './goals-data.js';
import { STAR, cleanMask } from './challenges.js';
import { rleIntervals } from './discovery.js';
import { liftKey } from './goals-keys.js';

export const PARK_GOAL_POINTS = 5000;
const STAR_SHARE = 0.2;
const MIN_COLOUR = 3, MIN_PISTES = 10, MIN_LIFTS = 3;
const TOP_MARGIN = 25;                 // m below the highest lift top that count as "there"
const HASH = 5;
const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';

/** The goals in display order: id, bit in progress.goals[rid], label (Luxembourgish). */
export const GOAL_DEFS = Object.freeze([
  { id: 'lifts', bit: 1, label: 'All Lifte gefuer' },
  { id: 'black', bit: 2, label: 'All schwaarz Pisten' },
  { id: 'red', bit: 4, label: 'All rout Pisten' },
  { id: 'blue', bit: 8, label: 'All blo Pisten' },
  { id: 'green', bit: 16, label: 'All gréng Pisten' },
  { id: 'pistes', bit: 32, label: 'All Pisten' },
  { id: 'stars', bit: 64, label: 'Stäre gesammelt' },
  { id: 'disc', bit: 128, label: 'Ganz Gebitt entdeckt' },
  { id: 'top', bit: 256, label: 'Héchste Punkt' },
  { id: 'park', bit: 512, label: 'Snowpark gefuer' },
  { id: 'parkpts', bit: 1024, label: `${PARK_GOAL_POINTS.toLocaleString('de-LU')} Punkten am Park` },
]);
const COLOUR_CH = { black: 'k', red: 'r', blue: 'b', green: 'g' };

export const areaIds = () => Object.keys(GOALS_DATA);
export const hasArea = (rid) => Object.prototype.hasOwnProperty.call(GOALS_DATA, rid);
const bitsOf = (n) => { let c = 0; for (let v = n; v; v &= v - 1) c += 1; return c; };

/* ---------------- the indexes ---------------- */
const posCache = new Map();
function positionsOf(kind, rid, text) {
  const id = `${kind}/${rid}`;
  if (!posCache.has(id)) {
    const map = new Map();
    for (let i = 0; i + HASH <= (text || '').length; i += HASH) map.set(text.slice(i, i + HASH), i / HASH);
    posCache.set(id, map);
  }
  return posCache.get(id);
}
export const pistePos = (rid, hash) => { const p = positionsOf('p', rid, PISTE_INDEX[rid]).get(hash); return p === undefined ? -1 : p; };
export const liftPos = (rid, key) => { const p = positionsOf('l', rid, LIFT_INDEX[rid]).get(key); return p === undefined ? -1 : p; };
export const pisteHashAt = (rid, pos) => (PISTE_INDEX[rid] || '').slice(pos * HASH, pos * HASH + HASH);
export const liftKeyAt = (rid, pos) => (LIFT_INDEX[rid] || '').slice(pos * HASH, pos * HASH + HASH);

/* ---------------- lifts ridden: one bit per index position, 6 per base64 character ---------------- */
export const cleanLifts = (text) => (typeof text === 'string' && text.length <= 400 && /^[A-Za-z0-9_-]+$/.test(text) ? text : '');
function liftBit(text, pos) { const v = B64.indexOf(text[Math.floor(pos / 6)] || 'A'); return v >= 0 && ((v >> (pos % 6)) & 1) === 1; }
/** The union of two lift texts. */
export function mergeLifts(a, b) {
  const x = cleanLifts(a), y = cleanLifts(b), n = Math.max(x.length, y.length);
  let out = '';
  for (let i = 0; i < n; i++) out += B64[(B64.indexOf(x[i] || 'A') | B64.indexOf(y[i] || 'A')) & 63];
  return out.replace(/A+$/, '');
}
/** A NEW progress with the lift (a resort.json lift) marked as ridden; the same object when it is known already or not in the index. */
export function markLift(progress, rid, lift) {
  const key = liftKey(lift), pos = key ? liftPos(rid, key) : -1;
  if (pos < 0) return progress;
  const text = cleanLifts((progress.lifts || {})[rid]);
  if (liftBit(text, pos)) return progress;
  const chars = text.padEnd(Math.floor(pos / 6) + 1, 'A').split('');
  chars[Math.floor(pos / 6)] = B64[B64.indexOf(chars[Math.floor(pos / 6)]) | (1 << (pos % 6))];
  return { ...progress, lifts: { ...(progress.lifts || {}), [rid]: chars.join('') } };
}
export function liftsRidden(progress, rid) {
  const data = GOALS_DATA[rid];
  if (!data) return { have: 0, need: 0 };
  const text = cleanLifts((progress.lifts || {})[rid]);
  let have = 0, need = 0;
  for (let i = 0; i < data.ld.length; i++) if (data.ld[i] === '1') { need++; if (liftBit(text, i)) have++; }
  return { have, need };
}

/** Number of discovered cells in a run-length text (modes/discovery.js). */
export const discCount = (text) => rleIntervals(text).reduce((n, [a, b]) => n + (b - a), 0);

/* ---------------- the goals of one area ---------------- */
const areaCache = new Map();
/** [{ def, need }] of the goals that exist in this area (a colour with fewer than 3 pistes, a resort without a park have none). */
export function areaGoals(rid) {
  if (areaCache.has(rid)) return areaCache.get(rid);
  const data = GOALS_DATA[rid], out = [];
  if (data) {
    const count = (ch) => { let n = 0; for (const c of data.pd) if (c === ch) n++; return n; };
    const total = [...data.pd].filter((c) => c !== '-').length;
    const lifts = [...data.ld].filter((c) => c === '1').length;
    for (const def of GOAL_DEFS) {
      let need = 0;
      if (def.id === 'lifts') need = lifts >= MIN_LIFTS ? lifts : 0;
      else if (COLOUR_CH[def.id]) { const n = count(COLOUR_CH[def.id]); need = n >= MIN_COLOUR ? n : 0; }
      else if (def.id === 'pistes') need = total >= MIN_PISTES ? total : 0;
      else if (def.id === 'stars') need = total >= MIN_PISTES ? Math.max(10, Math.round(total * 3 * STAR_SHARE / 5) * 5) : 0;
      else if (def.id === 'disc') need = data.dn > 0 ? data.dn : 0;
      else if (def.id === 'top') need = data.top > 0 ? 1 : 0;
      else if (def.id === 'park') need = data.pk ? 1 : 0;
      else if (def.id === 'parkpts') need = data.pk ? PARK_GOAL_POINTS : 0;
      if (need > 0) out.push({ def, need });
    }
  }
  areaCache.set(rid, out);
  return out;
}

export const storedMask = (progress, rid) => { const m = (progress.goals || {})[rid]; return Number.isInteger(m) && m > 0 ? m & 2047 : 0; };

function starsOfArea(progress, rid) {
  let n = 0;
  const prefix = `${rid}/`;
  for (const [k, v] of Object.entries(progress.stars || {})) if (k.startsWith(prefix)) n += bitsOf(cleanMask(v));
  return n;
}

/** The progress of every goal of an area: [{ id, bit, label, have, need, earned, done }]. `extra` = { discCount } (the live discovery). */
export function goalProgress(progress, rid, extra = {}) {
  const data = GOALS_DATA[rid];
  if (!data) return [];
  const stored = storedMask(progress, rid);
  const stars = progress.stars || {};
  const tally = { k: [0, 0], r: [0, 0], b: [0, 0], g: [0, 0], all: [0, 0] };
  for (let i = 0; i < data.pd.length; i++) {
    const ch = data.pd[i];
    if (ch === '-') continue;
    const done = (cleanMask(stars[`${rid}/${pisteHashAt(rid, i)}`]) & STAR.finish) !== 0 ? 1 : 0;
    tally[ch][0] += done; tally[ch][1]++; tally.all[0] += done; tally.all[1]++;
  }
  const lifts = liftsRidden(progress, rid);
  const disc = Number.isFinite(extra.discCount) ? extra.discCount : discCount((progress.disc || {})[rid]);          // the live count (HUD rate) is never smaller than the saved one
  const park = (progress.park || {})[rid] || 0;
  return areaGoals(rid).map(({ def, need }) => {
    let have = 0;
    if (def.id === 'lifts') have = lifts.have;
    else if (COLOUR_CH[def.id]) have = tally[COLOUR_CH[def.id]][0];
    else if (def.id === 'pistes') have = tally.all[0];
    else if (def.id === 'stars') have = starsOfArea(progress, rid);
    else if (def.id === 'disc') have = disc;
    else if (def.id === 'top') have = 0;
    else if (def.id === 'park') have = park > 0 ? 1 : 0;
    else if (def.id === 'parkpts') have = park;
    const earned = (stored & def.bit) !== 0;
    const done = earned || have >= need || (def.id === 'top' && extra.top === true);
    return { id: def.id, bit: def.bit, label: def.label, have: done ? need : Math.min(have, need), need, earned, done };
  });
}

/** Check an area: { progress (NEW, with the reached goals in progress.goals; the same object when nothing is new), gained: [goal rows] }.
 *  extra = { discCount, top } (the live discovery; top: the skier came to the highest point). */
export function checkGoals(progress, rid, extra = {}) {
  const rows = goalProgress(progress, rid, extra);
  const stored = storedMask(progress, rid);
  let mask = stored;
  const gained = [];
  for (const r of rows) if (r.done && !(stored & r.bit)) { mask |= r.bit; gained.push(r); }
  if (!gained.length) return { progress, gained };
  return { progress: { ...progress, goals: { ...(progress.goals || {}), [rid]: mask } }, gained };
}

/** Every area at once, silently (old saves earn their badges when the game starts). */
export function checkAll(progress) {
  let p = progress;
  const gained = [];
  for (const rid of areaIds()) { const r = checkGoals(p, rid); p = r.progress; gained.push(...r.gained.map((g) => ({ ...g, rid }))); }
  return { progress: p, gained };
}

/** The highest point: is this height (m) within TOP_MARGIN of the highest lift top of the area? */
export const atTop = (rid, y) => { const d = GOALS_DATA[rid]; return !!d && Number.isFinite(y) && y >= d.top - TOP_MARGIN; };

/** Badges of one area: { earned, total } (earned counts the stored bits of goals that exist in the area). */
export function badgeCount(progress, rid) {
  const stored = storedMask(progress, rid), goals = areaGoals(rid);
  return { earned: goals.filter(({ def }) => stored & def.bit).length, total: goals.length };
}
export function badgeTotals(progress) {
  let earned = 0, total = 0;
  for (const rid of areaIds()) { const c = badgeCount(progress, rid); earned += c.earned; total += c.total; }
  return { earned, total };
}
